pub(crate) fn general() -> String {
    format!(
        concat!(
            "Brain Brew {}\n",
            "Local-first deck federation tooling for Anki-compatible decks.\n\n",
            "Usage:\n",
            "  brainbrew <command> [options]\n\n",
            "Commands:\n",
            "  fmt       Format deck, overlay, manifest, or lock YAML in place\n",
            "  validate  Validate a deck file or manifest target\n",
            "  compose   Compose a base deck plus overlays into resolved CanonicalDeck YAML\n",
            "  export    Export a resolved deck to an adapter format, currently CrowdAnki\n",
            "  import    Bootstrap a new Canonical Deck workspace from CrowdAnki\n",
            "  lock      Update or verify locked federated package inputs\n",
            "  media     Verify and refresh declared media asset hashes\n",
            "  targets   List manifest targets\n",
            "  translations Report/apply translation coverage (aliases: translate, translation)\n",
            "  workbench Serve the local Deck Workbench browser UI and JSON API\n",
            "  verify    Run manifest formatting, composition, validation, media, and golden checks\n",
            "  explain   Explain a manifest target and its overlay stack\n",
            "  diff      Compare decks semantically, or emit an overlay draft\n\n",
            "Examples:\n",
            "  brainbrew targets --manifest brainbrew.yaml\n",
            "  brainbrew validate --manifest brainbrew.yaml --target da-standard\n",
            "  brainbrew compose --manifest brainbrew.yaml --target da-standard --out build/da.yaml\n",
            "  brainbrew compose --manifest america/brainbrew.yaml --include ultimate-geography/brainbrew.yaml --target en-america\n",
            "  brainbrew lock update --package anki-geo.ultimate-geography --path ../ultimate-geography\n",
            "  brainbrew media hash --manifest brainbrew.yaml --all-targets --media-root media/\n",
            "  brainbrew media images-to-refs --manifest brainbrew.yaml --all-targets\n",
            "  brainbrew export crowdanki --manifest brainbrew.yaml --target de-extended --media-root media/\n",
            "  brainbrew translate --manifest brainbrew.yaml --target de-standard\n",
            "  brainbrew workbench serve --manifest brainbrew.yaml\n",
            "  brainbrew verify --manifest brainbrew.yaml --all-targets --media-root media/\n\n",
            "Run `brainbrew <command> --help` for command-specific examples.\n",
        ),
        env!("CARGO_PKG_VERSION")
    )
}

pub(crate) fn command(name: &str) -> Option<&'static str> {
    match name {
        "fmt" => Some(
            "Usage:\n  brainbrew fmt <deck-or-overlay-or-manifest-or-lock.yaml>\n\nExamples:\n  brainbrew fmt deck.yaml\n  brainbrew fmt overlays/languages/da.yaml\n  brainbrew fmt brainbrew.yaml\n  brainbrew fmt brainbrew.lock\n",
        ),
        "validate" => Some(
            "Usage:\n  brainbrew validate <deck.yaml> [--overlay overlay.yaml ...] [--json]\n  brainbrew validate --manifest brainbrew.yaml --target <target> [--include package/brainbrew.yaml ...] [--package-root packages/] [--json]\n\nExamples:\n  brainbrew validate deck.yaml\n  brainbrew validate deck.yaml --overlay overlays/languages/da.yaml\n  brainbrew validate --manifest brainbrew.yaml --target da-standard\n  brainbrew validate --manifest america/brainbrew.yaml --include ultimate-geography/brainbrew.yaml --target en-america\n  brainbrew validate --manifest brainbrew.yaml --target de-extended --json\n",
        ),
        "compose" => Some(
            "Usage:\n  brainbrew compose <deck.yaml> [--overlay overlay.yaml ...] [--out resolved.yaml] [--force]\n  brainbrew compose [--manifest brainbrew.yaml] --target <target> [--include package/brainbrew.yaml ...] [--package-root packages/] [--out resolved.yaml] [--force]\n\nExamples:\n  brainbrew compose deck.yaml --overlay overlays/languages/da.yaml --out build/da.yaml\n  brainbrew compose --manifest brainbrew.yaml --target da-standard --out build/da.yaml\n  brainbrew compose --manifest america/brainbrew.yaml --include ultimate-geography/brainbrew.yaml --target en-america\n  brainbrew compose --manifest brainbrew.yaml --target da-standard\n\nCompose creates missing in-root output parents. Existing outputs are refused unless --force is supplied; forced replacement is fingerprint-checked, backed up, and recoverable.\n",
        ),
        "export" => Some(
            "Usage:\n  brainbrew export crowdanki <deck.yaml> [--overlay overlay.yaml ...] --out build/deck-folder [--media-root media/ | --media-mode reference-only] [--force] [--json]\n  brainbrew export crowdanki [--manifest brainbrew.yaml] --target <target> [--include package/brainbrew.yaml ...] [--package-root packages/] [--out build/deck-folder] [--media-root media/ | --media-root <package-id>=<dir> ... | --media-mode reference-only] [--force] [--json]\n\nExamples:\n  brainbrew export crowdanki deck.yaml --overlay overlays/languages/da.yaml --out build/da-crowdanki\n  brainbrew export crowdanki --manifest brainbrew.yaml --target da-standard --media-root media/\n  brainbrew export crowdanki --manifest america/brainbrew.yaml --include ultimate-geography/brainbrew.yaml --target en-america --out build/en-america\n  brainbrew export crowdanki --manifest brainbrew.yaml --target de-extended --media-root media/\n\nWhen --out is omitted for a manifest target, the output defaults to build/crowdanki/<target> unless exports.crowdanki.out is configured. Media targets are release-strict by default: every owner root, canonical hash, and byte must validate. --media-mode reference-only explicitly skips roots/bytes for development while retaining semantic checks and reporting NOT RELEASE-READY; a missing root never selects it. Existing output directories are refused unless --force is supplied. The complete clean tree is staged privately and then published with backup/recovery; stale files are never retained.\n",
        ),
        "import" => Some(
            "Usage:\n  brainbrew import crowdanki plan <deck-folder> --out import-plan.json [--media-root media/ | --media-mode reference-only] [--force] [--json]\n  brainbrew import crowdanki review --plan import-plan.json [--json]\n  brainbrew import crowdanki apply <deck-folder> --plan import-plan.json --approve-plan --out workspace-dir [--media-root media/ | --media-mode reference-only] [--force] [--json]\n\nExamples:\n  brainbrew import crowdanki plan build/de-extended --media-root build/de-extended/media --out import-plan.json\n  brainbrew import crowdanki review --plan import-plan.json\n  brainbrew import crowdanki apply build/de-extended --plan import-plan.json --approve-plan --media-root build/de-extended/media --out imported-workspace\n\nPlan generation writes no Canonical Deck source. Apply creates a complete new `deck.yaml` plus `media/` bootstrap workspace; it never merges into a federated source or overlay stack, and it has no base-versus-overlay ownership inference. Preserve existing source separately. In strict mode it inventories every declared CrowdAnki media path, authorizes it below the selected media root, reads each byte once, and records its SHA-256/length evidence in the review plan. Apply verifies exact source and media bytes before staging the clean recoverable output tree. The destination must not exist unless `--force` cleanly replaces that bootstrap output; symlinks and special targets are refused. `--media-mode reference-only` is explicit non-release behavior and records no byte claim. Automatic suggestions require the explicit reviewed acknowledgement `--approve-plan`; unresolved collisions require edited `override` decisions. The legacy `--accept-suggested-ids` flag is removed.\n",
        ),
        "lock" => Some(
            "Usage:\n  brainbrew lock update --package <package-id> (--path <dir> | --git <github-url> [--ref <ref>] [--rev <rev>] | --tarball <url>) [--package-manifest brainbrew.yaml] [--lock brainbrew.lock]\n  brainbrew lock verify [--lock brainbrew.lock]\n\nExperimental: lock/package federation works, but brainbrew.lock and the brainbrew lock CLI surface may change incompatibly.\n\nExamples:\n  brainbrew lock update --package anki-geo.ultimate-geography --path ../ultimate-geography\n  brainbrew lock update --package anki-geo.ultimate-geography --git https://github.com/anki-geo/ultimate-geography.git --ref main\n  brainbrew lock verify\n",
        ),
        "media" => Some(
            "Usage:\n  brainbrew media hash [--manifest brainbrew.yaml] (--all-targets | --target <target>) [--include package/brainbrew.yaml ...] [--package-root packages/] --media-root media/ [--media-root <package-id>=<dir> ...]\n  brainbrew media images-to-refs [--manifest brainbrew.yaml] (--all-targets | --target <target>) [--include package/brainbrew.yaml ...] [--package-root packages/]\n\nExamples:\n  brainbrew media hash --manifest brainbrew.yaml --all-targets --media-root media/\n  brainbrew media hash --manifest brainbrew.yaml --target en-standard --media-root media/\n  brainbrew media images-to-refs --manifest brainbrew.yaml --all-targets\n\n`media hash` computes SHA-256 hashes for declared media files and writes missing or stale values back to deck/overlay source YAML using the include-preserving canonical formatter.\n\n`media images-to-refs` converts whole-field strict `<img src=\"PATH\" />` source values to `!image <media-stable-id>` when PATH maps to exactly one declared media ID. Non-strict fields, undeclared paths, and duplicate path declarations stay raw and are counted in the report.\n",
        ),
        "targets" => Some(
            "Usage:\n  brainbrew targets [--manifest brainbrew.yaml] [--include package/brainbrew.yaml ...] [--package-root packages/] [--package-ignore <safe-relative-pattern> ...] [--discovery-max-depth <n>] [--discovery-max-entries <n>] [--discovery-max-manifests <n>] [--json]\n\nExamples:\n  brainbrew targets --manifest brainbrew.yaml\n  brainbrew targets --manifest brainbrew.yaml --json\n  brainbrew targets --package-root ../packages\n  brainbrew targets --package-root ../packages --package-ignore 'vendor/**/generated' --discovery-max-entries 200000\n\nAll commands accepting --package-root accept the same discovery flags. Defaults: depth=32, entries=100000, manifests=1000. Discovery is deterministic, never follows symlinks, prunes conventional VCS/build/output/cache trees by exact name, and reports actionable budget errors.\n",
        ),
        "translations" | "translate" | "translation" => Some(
            "Usage:\n  brainbrew translate [--manifest brainbrew.yaml] [--target <target> | --all-targets] [--language <code>] [--overlay <id-or-file>] [--note <note-id>] [--field <field-id>] [--source <text>] [--duplicates] [--status <status>] [--path-prefix <deck-path>] [--apply | --summary | --context] [--full] [--interactive | --no-interactive] [--json]\n  brainbrew translate [--manifest brainbrew.yaml] [--target <target> | --all-targets] [--language <code>] [--overlay <id-or-file>] [--note <note-id>] [--field <field-id>] [--status stale] [--path-prefix <deck-path>] --resolve (confirm | replace) [--old-source <text>] [--new-source <text>] [--stale-context <path>] [--translation <text>] [--json]\n\nInteractive examples:\n  brainbrew translate\n  brainbrew translate --manifest fixtures/ultimate-geography/brainbrew.yaml\n  brainbrew translate --interactive\n\nScriptable examples:\n  brainbrew translations --manifest brainbrew.yaml --target da-standard\n  brainbrew translations --manifest brainbrew.yaml --all-targets --language de\n  brainbrew translations --manifest brainbrew.yaml --target de-standard --note note.finland --field field.country\n  brainbrew translations --manifest brainbrew.yaml --target de-standard --context --source Georgia\n  brainbrew translations --manifest brainbrew.yaml --target da-standard --apply\n  brainbrew translations --manifest brainbrew.yaml --target da-standard --resolve confirm --old-source 'Old text' --new-source 'New text'\n  brainbrew translations --manifest brainbrew.yaml --target da-standard --resolve replace --old-source 'Old text' --new-source 'New text' --translation 'New translation'\n  brainbrew translations --manifest brainbrew.yaml --all-targets --summary --json\n  brainbrew translations --manifest brainbrew.yaml --target da-standard --json\n\nReport mode is the default and never edits files. In an interactive terminal, missing choices open arrow-key selectors for target, scope, and mode; language and overlay selectors appear only when they disambiguate the selected targets. The human report is translator-focused by default: structural/media/tag fallbacks are hidden and summarized. Use --full to include every scalar fallback. --context shows source and target strings in note/field/card context; combine it with --note, --field, --source, --duplicates, --status, and --language to navigate the translator context view. --summary exports compact per-language/per-overlay counts and de-duplicates identical reports across target variants; human summary output uses narrow aligned columns by default, and --summary --full adds overlay/file columns. --apply inserts source->source translation stubs for missing text fallbacks in non-interactive mode, while interactive apply lets you select rows with Space/Enter and choose one action for all selected rows (mark no-change, direct/contextual stub, ignore-path, skip) or decide per row. --resolve confirm promotes matching stale translations under the current source text; --resolve replace first uses the same stale-record resolution path, then installs the provided --translation. Omit --old-source/--new-source within a narrow target/overlay/scope to batch-resolve all matching current-base stale records. Use --path-prefix with paths from a diff to scope a changed-base review.\n",
        ),
        "workbench" => Some(
            "Usage:\n  brainbrew workbench serve [--manifest brainbrew.yaml] [--port <port>] [--no-open] [--dev-assets <dir>] [--media-root <dir> | --media-root <package-id>=<dir> ...]\n\nExamples:\n  brainbrew workbench serve --manifest brainbrew.yaml\n  brainbrew workbench serve --manifest brainbrew.yaml --port 0 --no-open\n  brainbrew workbench serve --manifest brainbrew.yaml --dev-assets target/workbench-ui\n  brainbrew workbench serve --manifest brainbrew.yaml --media-root media/\n\nStarts a read-only localhost Deck Workbench server bound to 127.0.0.1. Browsing, comparison, preview, and browser-local draft staging remain available, but normal and distributed binaries reject source mutation. Port 0 selects an available port. Release builds serve embedded UI assets from the brainbrew binary; --dev-assets serves a development asset directory such as the output of `devenv shell workbench-ui-watch`. Use --media-root to serve declared media assets from a directory outside the manifest root.\n\nUnsafe write-path development requires both a binary explicitly compiled with Cargo feature `workbench-write-dev` and the runtime flag `--enable-write`. The flag is rejected by normal binaries. This mode is unsupported for release use and is visibly/API marked as development-only.\n",
        ),
        "verify" => Some(
            "Usage:\n  brainbrew verify [--manifest brainbrew.yaml] (--all-targets | --target <target>) [--include package/brainbrew.yaml ...] [--package-root packages/] [--media-root media/ | --media-root <package-id>=<dir> ... | --media-mode reference-only] [--translation-coverage lenient|strict] [--skip-content-validation] [--json]\n\nExamples:\n  brainbrew verify --manifest brainbrew.yaml --all-targets\n  brainbrew verify --manifest brainbrew.yaml --target da-standard\n  brainbrew verify --manifest america/brainbrew.yaml --include ultimate-geography/brainbrew.yaml --target en-america\n  brainbrew verify --manifest brainbrew.yaml --all-targets --media-root media/\n  brainbrew verify --manifest brainbrew.yaml --target de-release --translation-coverage strict\n  brainbrew verify --manifest brainbrew.yaml --target legacy-sloppy-html --skip-content-validation\n\nMedia targets are release-strict by default: every final owner root, canonical non-empty SHA-256, and byte must validate. --media-mode reference-only is explicit non-release development mode and still validates references, collisions, safe paths, and present hash syntax. It reports NOT RELEASE-READY in human/JSON output and cannot be combined with --media-root. Targets without media are unaffected. Verify also checks rendered deck descriptions/card templates as lightweight HTML and note-type styling as balanced CSS. Use --skip-content-validation only for legacy false positives.\n",
        ),
        "explain" => Some(
            "Usage:\n  brainbrew explain [--manifest brainbrew.yaml] --target <target> [--include package/brainbrew.yaml ...] [--package-root packages/] [--json]\n\nExamples:\n  brainbrew explain --manifest brainbrew.yaml --target da-standard\n  brainbrew explain --manifest america/brainbrew.yaml --include ultimate-geography/brainbrew.yaml --target en-america\n  brainbrew explain --manifest brainbrew.yaml --target de-extended --json\n",
        ),
        "diff" => Some(
            "Usage:\n  brainbrew diff <left.yaml> <right.yaml> [--json] [--exit-code]\n  brainbrew diff <left.yaml> <right.yaml> --as-overlay --id <overlay-id> [--kind patch]\n\nExamples:\n  brainbrew diff deck.yaml edited.yaml\n  brainbrew diff deck.yaml edited.yaml --json --exit-code\n  brainbrew diff deck.yaml edited.yaml --as-overlay --id overlay.patch.capitals --kind patch\n\nWith --exit-code, no differences exit 0, semantic differences exit 2 after printing the normal report, and operational errors exit 1.\n",
        ),
        _ => None,
    }
}

pub(crate) fn usage_error(command: &str, fallback: &str) -> String {
    self::command(command)
        .map(str::to_owned)
        .unwrap_or_else(|| fallback.to_owned())
}
